import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Doygunluk ve canlılık; ikisi de renkleri güçlendirir ama farklı çalışır. Biri tüm renkleri eşit artırır, diğeri soluk renkleri seçer.</p>\n<p>Yanlış kontrol, ten renklerini bozar. Doygunluk gereken yerde canlılık, canlılık gereken yerde doygunluk kullanmak fark yaratır.</p>\n<p>Bu yazı, iki kontrolün nasıl çalıştığını, ten renklerini hangisinin koruduğunu ve doğal renk için nasıl birleştirileceklerini anlatıyor.</p>\n<h2 id=\"what-each-does\">Her kontrol ne yapar?</h2>\n<p>Doygunluk, tüm renklerin yoğunluğunu eşit artırır ya da azaltır. Kırmızı, mavi ve ten rengi birlikte değişir.</p>\n<p>Canlılık, soluk renkleri güçlendirir, doygun renkleri korur. Ten renkleri neredeyse hiç değişmez.</p>\n<p>İki kontrol de renkleri canlandırır ama canlılık daha akıllıdır.</p>\n<h2 id=\"how-saturation-works\">Doygunluk nasıl çalışır?</h2>\n<p>Doygunluk, her pikselin renk yoğunluğunu aynı oranda artırır. Zaten doygun renkler daha da doygun olur.</p>\n<p>Bu, ten renklerini bozar. Yüz, doygunluk artınca turuncu görünür.</p>\n<p>Doygunluk, basit ve güçlüdür. Küçük ayarlar, büyük fark yaratır.</p>\n<h2 id=\"how-vibrance-works\">Canlılık nasıl çalışır?</h2>\n<p>Canlılık, soluk pikselleri güçlendirir, doygun pikselleri korur. Gökyüzü canlanır, yüz doğal kalır.</p>\n<p>Canlılık, ten renklerini korur. Yüz, canlılık artınca turuncu olmaz.</p>\n<p>Canlılık, portrelerde idealdir. Renk canlanır, cilt doğal kalır.</p>\n<h2 id=\"key-differences\">Temel farklar, yan yana</h2>\n<p>Doygunluk tüm renkleri eşit artırır; canlılık soluk renkleri seçer. Bu, en büyük farktır.</p>\n<p>Doygunluk ten renklerini bozar; canlılık korur. Portrelerde canlılık kazanır.</p>\n<p>Doygunluk daha güçlüdür; canlılık daha naziktir. Aşırı canlılık bile nadiren yapay görünür.</p>\n<h2 id=\"skin-tones\">Ten renkleri: canlılığın kazandığı yer</h2>\n<p>Ten renkleri, doygunluğa çok hassastır. Fazla doygunluk cildi turuncu yapar.</p>\n<p>Canlılık, ten renklerini korur. Portrelerde canlılığı +20 ile +30 arasında kullanın.</p>\n<p>Yüzü kontrol edin. Ten rengi doğal görünmüyorsa doygunluğu azaltın, canlılığı artırın.</p>\n<h2 id=\"landscapes\">Manzaralar: iki kontrol de işe yarar</h2>\n<p>Manzaralarda ten rengi yoktur; iki kontrol de güvenle kullanılır. Doygunluk ve canlılık birlikte artırılabilir.</p>\n<p>Gökyüzü ve çimen, iki kontrolle de canlanır. Fark, doygunluğun daha güçlü olmasıdır.</p>\n<p>Yeşili kontrol edin. Aşırı yeşil, yapay görünür; iki kontrolde de sınırı aşmayın.</p>\n<h2 id=\"when-to-use-saturation\">Doygunluk ne zaman kullanılmalı?</h2>\n<p>Ürün fotoğraflarında doygunluk kullanın. Renk doğruluğu kritiktir; tüm renkler eşit artmalıdır.</p>\n<p>Siyah beyaza çevirmek için doygunluğu sıfırlayın. Canlılık, siyah beyaza çeviremez.</p>\n<p>Soluk görünüm için doygunluğu azaltın. Renkler eşit solar; zarif görünüm oluşur.</p>\n<h2 id=\"when-to-use-vibrance\">Canlılık ne zaman kullanılmalı?</h2>\n<p>Portrelerde canlılık kullanın. Ten renkleri korunur, arka plan canlanır.</p>\n<p>Manzaralarda canlılık kullanın. Gökyüzü canlanır, yeşil doğal kalır.</p>\n<p>Güvenli renk artışı için canlılık kullanın. Aşırı canlılık bile nadiren yapay görünür.</p>\n<h2 id=\"combining-both\">Doygunluk ve canlılığı birleştirmek</h2>\n<p>İki kontrol birlikte kullanılabilir. Önce canlılığı artırın, sonra doygunluğu ince ayarlayın.</p>\n<p>Birleştirme, her alan için en iyi sonucu verir. Yüz doğal, manzara canlı olur.</p>\n<p>İkisini birlikte abartmayın. Aşırı renk, fotoğrafı yapay gösterir.</p>\n<h2 id=\"over-saturation-signs\">Aşırı doygunluk belirtileri</h2>\n<p>Ten rengi turuncu görünüyorsa aşırıya kaçtınız. Cilt doğal olmalıdır.</p>\n<p>Çimen neon yeşil görünüyorsa aşırıya kaçtınız. Yeşil, doğal kalmalıdır.</p>\n<p>Gökyüzü elektrik mavisi görünüyorsa aşırıya kaçtınız. Mavi, doğal kalmalıdır.</p>\n<h2 id=\"natural-colour-editing\">Doğal renk düzenleme: bir felsefe</h2>\n<p>Doğal renk, gerçeğe yakın renktir. Fotoğraf, gözün gördüğü gibi görünmelidir.</p>\n<p>Az düzenleme, çok düzenlemeden iyidir. +10 ile +20 arası, çoğu fotoğraf için yeterlidir.</p>\n<p>Karşılaştırma modunu kullanın. Orijinali gördükçe ayarı durdurursunuz.</p>\n<h2 id=\"muted-looks\">Soluk görünümler: az renk çokken</h2>\n<p>Soluk görünüm, doygunluğu azaltır. Zarif ve sakin bir his verir.</p>\n<p>Düğün ve portrelerde soluk renkler tercih edilir; yumuşak tonlar, bu tür fotoğraflara zarif bir hava verir.</p>\n<p>Soluk görünümde ölçüyü kaçırmayın; aşırı soluk fotoğraf, enerjisini kaybedip cansız durur.</p>\n<h2 id=\"black-and-white\">Siyah beyaz: en son doygunluk azaltma</h2>\n<p>Siyah beyaz, doygunluğu sıfıra indirir; renk kaybolur, fotoğrafta yalnızca açık ve koyu kalır.</p>\n<p>Siyah beyazda kontrast önemlidir. Kontrastı +10 ile +20 arasında tutun.</p>\n<p>Canlılık, siyah beyaza çeviremez. Yalnızca doygunluk sıfırlama, siyah beyaz yapar.</p>\n<h2 id=\"product-photos\">Ürün fotoğrafları: canlılıktan önce doğruluk</h2>\n<p>Ürün fotoğrafında renk doğruluğu hayati önem taşır; müşteri, gördüğü rengi aldığını bilmelidir.</p>\n<p>Ürün çekimlerinde doygunluğu +5 ile +10 aralığında bırakın; renk, gerçek ürünle birebir uymalıdır.</p>\n<p>Ekrandaki rengi gerçek ürünle yan yana koyup karşılaştırın; renkler birebir uymuyorsa doygunluğu düzeltin.</p>\n<h2 id=\"common-mistakes\">Renk kontrolleriyle yaygın hatalar</h2>\n<p>Doygunlukta en yaygın hata aşırıya kaçmaktır; +50'yi aşan değerler, renkleri doğallıktan koparır.</p>\n<p>Bir başka hata, ten renklerini bozmaktır. Portrelerde canlılık kullanın, doygunluğu düşük tutun.</p>\n<p>Üçüncü hata, orijinali silmektir. Düzenlenen görsel ayrı bir dosyadır; orijinali saklayın.</p>\n<h2 id=\"cheat-sheet\">Kontrol seçmek: hızlı kılavuz</h2>\n<p>Portre: canlılık +20 ile +30. Manzara: doygunluk +15 ile +25 ya da canlılık.</p>\n<p>Ürün: doygunluk +5 ile +10. Siyah beyaz: doygunluk sıfır.</p>\n<p>Bu listeyi kaydedin. Her düzenlemede yeniden düşünmek zaman kaybıdır.</p>\n<h2 id=\"vibrance-travel-photos\">Seyahat fotoğrafları için canlılık ve doygunluk</h2>\n<p>Seyahat fotoğraflarında canlılık kullanın. Gökyüzü ve deniz canlanır, yüzler doğal kalır.</p>\n<p>Canlılığı +20 ile +30 arasında tutun. Renkler canlı ama doğal görünür.</p>\n<p>Yeşil tonları kontrol edin. Aşırı yeşil, yapay görünür.</p>\n<p>Özetle: portre için canlılık, ürün için doygunluk; ikisi birlikte dengeli kullanılır. Adımlar için <a href=\"/tr/blog/gorsel-doygunlugu-nasil-ayarlanir\">Görsel doygunluğu nasıl ayarlanır</a> yazısına bakın; kılavuzun tamamı <a href=\"/tr/blog/gorsel-doygunluk-duzenleyici-rehberi\">Doygunluk düzenleyici kılavuzunda</a>. Filtreler için <a href=\"/tr/gorsel-filtreleri\">görsel filtreler</a> hazırdır; araç ise <a href=\"/tr/gorsel-doygunluk-ayarla\">görsel doygunluk düzenleyici</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Doygunluk ile canlılık arasındaki fark nedir?","answer":"Doygunluk tüm renklerin yoğunluğunu eşit artırır; canlılık soluk renkleri güçlendirir, doygun renkleri ve ten renklerini korur. Portrelerde canlılık kazanır; ürün fotoğraflarında doygunluk daha doğrudur."},{"question":"Portreler için doygunluk mu canlılık mı daha iyi?","answer":"Canlılık daha iyidir. Ten renklerini koruyarak arka planı canlandırır. Doygunluk, yüzü turuncu yapar. Portrelerde canlılığı +20 ile +30 arasında, doygunluğu +10 ile +15 arasında tutun."},{"question":"Doygunluk ve canlılığı aynı fotoğrafta kullanabilir miyim?","answer":"Evet. Önce canlılığı artırın, sonra doygunluğu ince ayarlayın. Birleştirme, her alan için en iyi sonucu verir; yüz doğal, manzara canlı olur. İkisini birlikte abartmayın."},{"question":"Manzaram renkleri artırdıktan sonra neden sahte görünüyor?","answer":"Çünkü doygunluğu fazla artırdınız; yeşil neon, gökyüzü elektrik mavisi oldu. Doygunluğu azaltın ya da canlılık kullanın. +30'un üzeri çoğu fotoğrafta yapay görünür."},{"question":"Canlılık fotoğrafımın parlaklığını değiştirir mi?","answer":"Çok az. Canlılık renkleri güçlendirir ama parlaklığı neredeyse hiç değiştirmez. Doygunluk artınca fotoğraf daha parlak görünür. Parlaklık için parlaklık kaydırıcısını kullanın."},{"question":"Ürün fotoğrafları için doygunluk mu canlılık mı kullanmalıyım?","answer":"Doygunluk kullanın. Ürün fotoğraflarında renk doğruluğu kritiktir; tüm renkler eşit artmalıdır. Doygunluğu +5 ile +10 arasında tutun. Ürünü gerçek renkle karşılaştırın."}];
